// Package store provides a concurrency-safe in-memory key-value store.
package store

import (
	"slices"
	"sync"
)

// Store holds raw byte values keyed by string. The zero value is not usable;
// create one with New.
type Store struct {
	mu   sync.RWMutex
	data map[string][]byte
}

// New returns an empty store.
func New() *Store {
	return &Store{data: make(map[string][]byte)}
}

// Put stores value under key and reports whether the key was newly created.
// The store takes ownership of value.
func (s *Store) Put(key string, value []byte) (created bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, exists := s.data[key]
	s.data[key] = value
	return !exists
}

// Get returns the value stored under key. The returned slice must not be modified.
func (s *Store) Get(key string) ([]byte, bool) {
	s.mu.RLock()
	defer s.mu.RUnlock()
	v, ok := s.data[key]
	return v, ok
}

// Delete removes key and reports whether it was present.
func (s *Store) Delete(key string) bool {
	s.mu.Lock()
	defer s.mu.Unlock()
	_, ok := s.data[key]
	delete(s.data, key)
	return ok
}

// Keys returns all keys sorted ascending. The result is never nil.
func (s *Store) Keys() []string {
	s.mu.RLock()
	keys := make([]string, 0, len(s.data))
	for k := range s.data {
		keys = append(keys, k)
	}
	s.mu.RUnlock()
	slices.Sort(keys)
	return keys
}

package store

import (
	"slices"
	"testing"
)

func TestStore(t *testing.T) {
	s := New()
	if got := s.Keys(); got == nil || len(got) != 0 {
		t.Fatalf("Keys on empty store = %#v, want empty non-nil", got)
	}
	if !s.Put("b", []byte("2")) {
		t.Fatal("first Put should report created")
	}
	if s.Put("b", []byte("3")) {
		t.Fatal("second Put should report replaced")
	}
	s.Put("a", []byte("1"))
	if v, ok := s.Get("b"); !ok || string(v) != "3" {
		t.Fatalf("Get(b) = %q, %v", v, ok)
	}
	if got := s.Keys(); !slices.Equal(got, []string{"a", "b"}) {
		t.Fatalf("Keys = %v", got)
	}
	if !s.Delete("a") || s.Delete("a") {
		t.Fatal("Delete should succeed once")
	}
	if _, ok := s.Get("a"); ok {
		t.Fatal("deleted key still present")
	}
}

// Command app is an in-memory HTTP/1.1 key-value server.
//
// Usage: app <port>
package main

import (
	"context"
	"errors"
	"fmt"
	"log"
	"net"
	"net/http"
	"os"
	"os/signal"
	"strconv"
	"syscall"
	"time"

	"kvhttp/internal/store"
)

func main() {
	if len(os.Args) != 2 {
		usage()
	}
	port, err := strconv.Atoi(os.Args[1])
	if err != nil || port < 1 || port > 65535 {
		usage()
	}
	if err := run(port); err != nil {
		log.Fatalf("server error: %v", err)
	}
}

func usage() {
	fmt.Fprintln(os.Stderr, "usage: app <port>")
	os.Exit(2)
}

func run(port int) error {
	ln, err := net.Listen("tcp", net.JoinHostPort("127.0.0.1", strconv.Itoa(port)))
	if err != nil {
		return err
	}

	srv := &http.Server{
		Handler:           newServer(store.New()),
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       60 * time.Second,
		WriteTimeout:      60 * time.Second,
		IdleTimeout:       30 * time.Second,
		ErrorLog:          log.New(os.Stderr, "http: ", log.LstdFlags),
	}
	srv.SetKeepAlivesEnabled(false)

	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()

	errc := make(chan error, 1)
	go func() { errc <- srv.Serve(ln) }()

	select {
	case err := <-errc:
		if errors.Is(err, http.ErrServerClosed) {
			return nil
		}
		return err
	case <-ctx.Done():
		shutdownCtx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
		defer cancel()
		return srv.Shutdown(shutdownCtx)
	}
}

package main

import (
	"encoding/json"
	"errors"
	"io"
	"log"
	"net/http"
	"strconv"
	"strings"

	"kvhttp/internal/store"
)

// maxValueBytes is the largest value accepted by PUT /kv/<key>.
const maxValueBytes = 1 << 20

const kvPrefix = "/kv/"

// server routes HTTP requests to the key-value store.
type server struct {
	store *store.Store
}

func newServer(s *store.Store) *server {
	return &server{store: s}
}

// ServeHTTP dispatches on the raw (still-escaped) request path so that
// percent-encoded characters are never accepted as part of a key.
func (s *server) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	// One request per connection; any unread body is discarded.
	w.Header().Set("Connection", "close")

	path := r.URL.EscapedPath()
	switch {
	case path == "/health":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		send(w, http.StatusOK, "text/plain", []byte("ok"))
	case path == "/kv":
		if r.Method != http.MethodGet {
			methodNotAllowed(w, http.MethodGet)
			return
		}
		s.handleList(w)
	case strings.HasPrefix(path, kvPrefix):
		key := path[len(kvPrefix):]
		if !validKey(key) {
			send(w, http.StatusBadRequest, "", nil)
			return
		}
		s.handleKey(w, r, key)
	default:
		send(w, http.StatusNotFound, "", nil)
	}
}

func (s *server) handleList(w http.ResponseWriter) {
	body, err := json.Marshal(s.store.Keys())
	if err != nil {
		log.Printf("encode keys: %v", err)
		send(w, http.StatusInternalServerError, "", nil)
		return
	}
	send(w, http.StatusOK, "application/json", body)
}

func (s *server) handleKey(w http.ResponseWriter, r *http.Request, key string) {
	switch r.Method {
	case http.MethodGet:
		value, ok := s.store.Get(key)
		if !ok {
			send(w, http.StatusNotFound, "", nil)
			return
		}
		send(w, http.StatusOK, "application/octet-stream", value)
	case http.MethodPut:
		value, err := readBody(w, r, maxValueBytes)
		if err != nil {
			var tooLarge *http.MaxBytesError
			if errors.As(err, &tooLarge) {
				send(w, http.StatusRequestEntityTooLarge, "", nil)
			} else {
				send(w, http.StatusBadRequest, "", nil)
			}
			return
		}
		status := http.StatusOK
		if s.store.Put(key, value) {
			status = http.StatusCreated
		}
		send(w, status, "", nil)
	case http.MethodDelete:
		status := http.StatusNotFound
		if s.store.Delete(key) {
			status = http.StatusNoContent
		}
		send(w, status, "", nil)
	default:
		methodNotAllowed(w, http.MethodGet, http.MethodPut, http.MethodDelete)
	}
}

// readBody reads the full request body, failing with *http.MaxBytesError if
// it exceeds limit bytes.
func readBody(w http.ResponseWriter, r *http.Request, limit int64) ([]byte, error) {
	if r.ContentLength > limit {
		return nil, &http.MaxBytesError{Limit: limit}
	}
	return io.ReadAll(http.MaxBytesReader(w, r.Body, limit))
}

// validKey reports whether key matches [A-Za-z0-9_-]{1,64}.
func validKey(key string) bool {
	if len(key) == 0 || len(key) > 64 {
		return false
	}
	for i := 0; i < len(key); i++ {
		c := key[i]
		switch {
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9', c == '_', c == '-':
		default:
			return false
		}
	}
	return true
}

func methodNotAllowed(w http.ResponseWriter, allowed ...string) {
	w.Header().Set("Allow", strings.Join(allowed, ", "))
	send(w, http.StatusMethodNotAllowed, "", nil)
}

// send writes a complete response with an explicit Content-Length.
func send(w http.ResponseWriter, status int, contentType string, body []byte) {
	h := w.Header()
	if contentType != "" {
		h.Set("Content-Type", contentType)
	}
	if status != http.StatusNoContent {
		h.Set("Content-Length", strconv.Itoa(len(body)))
	}
	w.WriteHeader(status)
	if len(body) > 0 {
		if _, err := w.Write(body); err != nil {
			log.Printf("write response: %v", err)
		}
	}
}

package main

import (
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"

	"kvhttp/internal/store"
)

func TestRoutes(t *testing.T) {
	h := newServer(store.New())
	steps := []struct {
		method, path, body string
		status             int
		want               string
	}{
		{"GET", "/health", "", 200, "ok"},
		{"POST", "/health", "", 405, ""},
		{"GET", "/nope", "", 404, ""},
		{"GET", "/kv/", "", 400, ""},
		{"GET", "/kv/a.b", "", 400, ""},
		{"GET", "/kv/a/b", "", 400, ""},
		{"GET", "/kv/" + strings.Repeat("a", 65), "", 400, ""},
		{"PUT", "/kv/b", "2", 201, ""},
		{"PUT", "/kv/a", "1", 201, ""},
		{"PUT", "/kv/a", "x", 200, ""},
		{"GET", "/kv/a", "", 200, "x"},
		{"PATCH", "/kv/a", "", 405, ""},
		{"GET", "/kv", "", 200, `["a","b"]`},
		{"DELETE", "/kv/a", "", 204, ""},
		{"DELETE", "/kv/a", "", 404, ""},
		{"GET", "/kv/a", "", 404, ""},
		{"PUT", "/kv/big", strings.Repeat("z", maxValueBytes+1), 413, ""},
	}
	for _, s := range steps {
		req := httptest.NewRequest(s.method, s.path, strings.NewReader(s.body))
		rec := httptest.NewRecorder()
		h.ServeHTTP(rec, req)
		if rec.Code != s.status {
			t.Errorf("%s %s: status %d, want %d", s.method, s.path, rec.Code, s.status)
		}
		if got := rec.Body.String(); got != s.want {
			t.Errorf("%s %s: body %q, want %q", s.method, s.path, got, s.want)
		}
	}
}

func TestListEmpty(t *testing.T) {
	rec := httptest.NewRecorder()
	newServer(store.New()).ServeHTTP(rec, httptest.NewRequest(http.MethodGet, "/kv", nil))
	if rec.Body.String() != "[]" || rec.Header().Get("Content-Type") != "application/json" {
		t.Fatalf("got %q (%s)", rec.Body.String(), rec.Header().Get("Content-Type"))
	}
}
